window.addEventListener("load",function(){$(document).ready(function(){setTimeout(function(){let t=$(".recombinant-upload-field");t.length>0&&$(t).each(function(t,n){$(n).off("invalid.CustomMessage"),$(n).on("invalid.CustomMessage",function(t){$(n)[0].setCustomValidity($(n).attr("data-invalid-text"))}),$(n).on("change",function(t){$(n)[0].setCustomValidity("")})});let n=$(".recombinant-delete-field");n.length>0&&$(n).each(function(t,n){$(n).off("invalid.CustomMessage"),$(n).on("invalid.CustomMessage",function(t){$(n)[0].setCustomValidity($(n).attr("data-invalid-text"))}),$(n).on("change",function(t){$(n)[0].setCustomValidity("")})})},750);let t=$(".recombinant-org-field");t.length>0&&$(t).on("change",function(t){window.location.href=this.value})})});